import{_ as e,o as t,c as o,Q as i}from"./chunks/framework.b67c47e6.js";const m=JSON.parse('{"title":"Mobfile Generator","description":"","frontmatter":{},"headers":[],"relativePath":"guide/management/tools/index.md","filePath":"guide/management/tools/index.md","lastUpdated":1790618281000}'),a={name:"guide/management/tools/index.md"},n=i('<h1 id="mobfile-generator" tabindex="-1">Mobfile Generator <a class="header-anchor" href="#mobfile-generator" aria-label="Permalink to &quot;Mobfile Generator&quot;">​</a></h1><p>The <strong>Mobfile Generator</strong> makes machine files from model files you upload, without a project: no designs, no batches, no report. Use it to test a production line or a parsing setup, or to make files for panels that do not live in produuz.it.</p><p>You find it in the <strong>Files</strong> section of the company menu. It needs the <em>Mobfile Generator</em> module and a manager account. If the menu entry is greyed out, ask your administrator.</p><h2 id="making-files" tabindex="-1">Making files <a class="header-anchor" href="#making-files" aria-label="Permalink to &quot;Making files&quot;">​</a></h2><p>The screen has three parts:</p><ol><li><strong>Upload</strong> — drop the model files. Accepted: <code>.ifc</code>, <code>.btlx</code>, <code>.btl</code>, <code>.jjs</code> and <code>.wup</code>.</li><li><strong>Settings</strong> — pick the <strong>production line</strong> and the <strong>parsing setup</strong>, then adjust the job options of each machine station of that line. They start from the default job options of each machine setup. The options are explained on the <a href="/guide/machine_files/formats/panel_mob2/#job-options">MOB v2</a> page.</li><li><strong>Files</strong> — the history of your jobs, with their status, the files that went in and the files that came out.</li></ol><p>Press <strong>Generate</strong> to upload the files and start the job. The parsing setup is used for IFC and BTLx files.</p><h2 id="what-comes-out" tabindex="-1">What comes out <a class="header-anchor" href="#what-comes-out" aria-label="Permalink to &quot;What comes out&quot;">​</a></h2><p>One <code>output.zip</code> per job, with:</p><ul><li>one machine file per model file, holding the layers of every station of the line;</li><li>the operation drawings, in <code>pics/</code>;</li><li>the insulation CSV, when an Isolation station asks for it.</li></ul><p>The line decides the file format: MOB v1 when its Mobi One is a V1, MOB v2 when it is a V2. The line needs a Mobi One station whose machine setup has its configuration file uploaded. A line with Mobi One V1 and V2 stations together cannot be used.</p><h2 id="differences-with-project-files" tabindex="-1">Differences with project files <a class="header-anchor" href="#differences-with-project-files" aria-label="Permalink to &quot;Differences with project files&quot;">​</a></h2><ul><li>Multipanel groups do not apply: each model file is one panel.</li><li><strong>Switch direction Y-axis</strong> is applied only to BTLx files, and the Frame Station Y inversion is ignored.</li><li>A model file that fails is left out of the ZIP, and the job still shows as ready. Check that every file you uploaded is in the ZIP.</li></ul>',13),s=[n];function r(l,h,d,c,f,p){return t(),o("div",null,s)}const g=e(a,[["render",r]]);export{m as __pageData,g as default};
